{
  "tools": [
    {
      "name": "hammer_set_components",
      "title": "Set Components",
      "toolset": "hammer",
      "description": "Edit a map game object's components - add components, set their properties, remove them. Properties take the serialized forms hammer_get_node shows with includeComponentProperties. Everything validates before anything changes. Hammer can't undo component edits yet, so read the current values first if you might need to put them back.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "integer",
            "description": "The game object's node id, from hammer_find_nodes kind:GameObject."
          },
          "components": {
            "type": "object",
            "description": "A json object of component type to properties, e.g. {\"PointLight\": {\"Radius\": 512}}. A type the object doesn't have yet gets added."
          },
          "remove": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Component type names to remove."
          }
        },
        "required": [
          "id"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Angles": {
            "type": "string"
          },
          "Scale": {
            "type": "string"
          },
          "ChildCount": {
            "type": "integer"
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          },
          "EntityClassTitle": {
            "type": "string"
          },
          "KeyValues": {
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          },
          "Materials": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {}
              },
              "required": []
            }
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "InstanceTarget": {
            "type": "integer"
          },
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "set_component",
      "title": "Set Component",
      "toolset": "scene",
      "description": "Set properties on a component. Give the component's id, or its game object's id plus a type name. Values use the same serialized forms get_game_object shows - strings, numbers, 'x,y,z' vectors, colors as 'r,g,b,a', asset paths as strings. Everything validates before anything applies, and the user can undo it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The component's id, or its game object's id."
          },
          "properties": {
            "type": "object",
            "description": "A json object of property name to new value."
          },
          "type": {
            "type": "string",
            "description": "The component type to change, when id is a game object."
          }
        },
        "required": [
          "id",
          "properties"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "Applied": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}
